<?php
declare(strict_types=1);namespace App\Modules\SupplierInvoices\Controllers;
use App\Core\Exceptions\BusinessRuleException;use App\Core\Exceptions\ValidationException;use App\Core\Http\Csrf;use App\Core\Http\Request;use App\Core\Http\Response;use App\Core\Http\Session;use App\Core\View\View;use App\Modules\AccessControl\Services\AuthorizationService;use App\Modules\SupplierInvoices\Services\SupplierInvoiceService;use App\Modules\SupplierInvoices\Validators\SupplierInvoiceValidator;
final class SupplierInvoiceController{public function __construct(private readonly View$view,private readonly SupplierInvoiceService$s,private readonly SupplierInvoiceValidator$v,private readonly Csrf$csrf,private readonly Session$session,private readonly AuthorizationService$auth){}public function index(Request$r):Response{return Response::html($this->view->render('modules/supplier-invoices/index',['title'=>'فواتير الموردين','references'=>$this->s->references(),'canCreate'=>$this->auth->can('supplier_invoices.create')]));}public function create(Request$r):Response{return$this->form(null,[]);}public function store(Request$r):Response{return$this->save($r,null);}public function edit(Request$r):Response{$d=$this->s->details((int)$r->route('id'));if($d['invoice']['status']!=='draft')return Response::redirect('/supplier-invoices/'.$d['invoice']['id']);return$this->form($d['invoice'],$d['lines']);}public function update(Request$r):Response{return$this->save($r,(int)$r->route('id'));}public function show(Request$r):Response{$d=$this->s->details((int)$r->route('id'));return Response::html($this->view->render('modules/supplier-invoices/show',['title'=>'تفاصيل فاتورة المورد',...$d,'canEdit'=>$this->auth->can('supplier_invoices.edit'),'canApprove'=>$this->auth->can('supplier_invoices.approve'),'canCancel'=>$this->auth->can('supplier_invoices.cancel')]));}public function print(Request$r):Response{$d=$this->s->details((int)$r->route('id'));if($d['invoice']['status']!=='approved')throw new BusinessRuleException('الطباعة متاحة للفواتير المعتمدة فقط.');return Response::html($this->view->render('modules/supplier-invoices/print',['title'=>'طباعة فاتورة مورد',...$d],'layouts/print'));}public function approve(Request$r):Response{return$this->action($r,'approve','تم اعتماد فاتورة المورد وإنشاء تكاليف المشروع.');}public function cancel(Request$r):Response{return$this->action($r,'cancel','تم إلغاء مسودة الفاتورة.');}
private function form(?array$i,array$lines):Response{return Response::html($this->view->render('modules/supplier-invoices/form',['title'=>$i?'تعديل فاتورة مورد':'إنشاء فاتورة مورد','invoice'=>$i,'lines'=>$lines,'references'=>$this->s->references()]));}private function save(Request$r,?int$id):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);try{$saved=$this->s->save($this->v->validate($r->all()),$id);$this->flash('success','تم الحفظ','تم حفظ مسودة فاتورة المورد.');return Response::redirect('/supplier-invoices/'.$saved.'/edit');}catch(ValidationException|BusinessRuleException$e){$m=$e instanceof ValidationException?(string)reset($e->errors[array_key_first($e->errors)]):$e->getMessage();$this->flash('error','تعذر الحفظ',$m);return Response::redirect($id?'/supplier-invoices/'.$id.'/edit':'/supplier-invoices/create');}}private function action(Request$r,string$a,string$m):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);$id=(int)$r->route('id');try{$this->s->{$a}($id);$this->flash('success','تم التحديث',$m);}catch(BusinessRuleException$e){$this->flash('error','تعذر التحديث',$e->getMessage());}return Response::redirect('/supplier-invoices/'.$id);}private function flash(string$type,string$title,string$text):void{$this->session->flash('alert',['type'=>$type,'title'=>$title,'text'=>$text]);}}
